import{_ as t,l as i,o as a,c as p,v as n,p as l,x as r,d as s,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"Spence 市场信号原文","description":"","frontmatter":{"title":"Spence 市场信号原文","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/spence-1973.md","filePath":"econ/spence-1973.md","lastUpdated":1789023840000}'),d={name:"econ/spence-1973.md"};function h(B,e,A,m,f,_){const o=i("Mermaid");return a(),p("div",null,[e[1]||(e[1]=n('<h1 id="spence-市场信号原文" tabindex="-1">Spence 市场信号原文 <a class="header-anchor" href="#spence-市场信号原文" aria-label="Permalink to &quot;Spence 市场信号原文&quot;">​</a></h1><div class="epigraph"><p>教育不必提高生产率；只要信号对高能力更便宜，雇主就可以用它把类型分开。</p><footer>—— Spence, Job Market Signaling, Quarterly Journal of Economics 1973</footer></div><p><a href="/econ/akerlof-1970">上一课</a>（Akerlof 柠檬市场原文）。附录对照。主干<a href="/econ/spence-signaling">信号发送</a>已取分离均衡与单交叉。本篇对照 <strong>Spence 1973 原文</strong>：劳动力市场里的教育作为信号，信息均衡（informational equilibrium）的定义，以及过度教育作为均衡现象。不把<a href="/econ/akerlof-1970">柠檬</a>的供需螺旋再写一遍——Akerlof 是质量不可验证且无行动；Spence 给了类型一个有成本的可观察行动。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>雇主在雇佣时看不见生产率，只看得见教育年数一类指标。若教育不进入生产函数，古典理论会说它是浪费。Spence 的缺口是：浪费也可以是信息。高生产率工人获得同样教育的成本更低（时间、痛苦、补考），于是存在一套工资–教育日程，使高类型愿意读到雇主能认出他们、低类型不愿意模仿。市场可以在分离处站住，即使教育的社会边际产品为零。</p><p>原文用「信息均衡」而不是后来的完美贝叶斯：信念与选择一致，工资等于该教育水平下的条件期望生产率。多重均衡被明确写出——不同的教育门槛都可以自洽，福利可以比无信号时更差。</p><p><span class="marginnote">单交叉（Spence–Mirrlees）在原文里以「成本对能力递减」出现，尚未成为机制设计的标准术语。信号是发送者先行动；筛选是接收者设计菜单，下一篇 Rothschild–Stiglitz。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两类工人，生产率 \\(1\\) 与 \\(2\\)，教育成本 \\(c(e,\\theta)\\)，\\(\\theta\\) 高则成本低。雇主给出工资函数 \\(w(e)\\)。工人选 \\(e\\) 最大化 \\(w(e)-c(e,\\theta)\\)。均衡要求：\\(w(e)\\) 等于选择该 \\(e\\) 的工人的平均生产率；若某 \\(e\\) 无人选，信念仍需指定。分离均衡里两类选不同 \\(e\\)，工资等于各自生产率；混同均衡里两类选同一 \\(e\\)，工资等于先验平均。</p>',9)),(a(),l(E,null,{default:r(()=>[c(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TYPE%5B%22%E7%A7%81%E6%9C%89%E8%83%BD%E5%8A%9B%22%5D%20--%3E%20EDU%5B%22%E9%80%89%E6%8B%A9%E6%95%99%E8%82%B2%20e%22%5D%0A%20%20EDU%20--%3E%20W%5B%22%E5%B7%A5%E8%B5%84%20%3D%20%E8%AF%A5%20e%20%E7%9A%84%E6%9D%A1%E4%BB%B6%E6%9C%9F%E6%9C%9B%E4%BA%A7%E5%87%BA%22%5D%0A%20%20W%20--%3E%20SEP%5B%22%E5%88%86%E7%A6%BB%3A%20%E9%AB%98%E7%B1%BB%E5%9E%8B%E8%AF%BB%E5%88%B0%E6%A8%A1%E4%BB%BF%E5%88%9A%E5%A5%BD%E4%B8%8D%E5%80%BC%22%5D%0A%20%20W%20--%3E%20POOL%5B%22%E6%B7%B7%E5%90%8C%3A%20%E5%85%B1%E5%90%8C%20e%2C%20%E5%B9%B3%E5%9D%87%E5%B7%A5%E8%B5%84%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>原文强调教育可以完全是信号。后文的人力资本理论把教育同时写成生产与信号；1973 年论文为了钉机制，先把生产效应关掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是差别成本使模仿有代价。工资日程必须陡到让低类型在「装作高类型」上无利可图，又不能陡到让高类型也不愿分离。Akerlof 的价格是一维的，只能反映平均质量；Spence 的 \\(w(e)\\) 是函数，维度够用来分离。代价是可能的过度投资：社会不需要那么多 \\(e\\)，私人却需要它当门票。这与福利定理的对照是：信息均衡可以存在且帕累托劣于无信号的混同——竞争不再自动有效。</p><h3 id="发送者先动-不是筛选" tabindex="-1">发送者先动，不是筛选 <a class="header-anchor" href="#发送者先动-不是筛选" aria-label="Permalink to &quot;发送者先动，不是筛选&quot;">​</a></h3><p>主干<a href="/econ/spence-signaling">信号发送</a>已用教育信号。附录钉原文：生产效应可以关掉，单交叉仍能分离；混同也是均衡，精炼是后十年的事。与<a href="/econ/pecking-order">优序</a>不要对读成同一篇——发股是坏类型更想做的行动，教育是低成本者更想发的信号。1973 年 QJE 不管公司金融。</p><p><span class="marginnote">Spence, <em>QJE</em> 87(3), 1973, 355–374。Job market signaling。义务教育改革的回归不能用来「证明或否证」这篇。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1973 写成已经精炼掉混同。Riley、Cho–Kreps 的直觉标准是后十年的工作；主干完美贝叶斯课才处理。也不要把文凭立法或义务教育当成原文的政策结论——原文是存在性与福利含混。经验上教育当然有生产效应；附录对照的是「即使没有，信号仍可撑起市场」。</p><p>下一篇对照保险公司作为筛选者：接收者出合同菜单，而不是发送者先选教育。本篇仍是附录，不插入柠檬主干课与信号主干课之间另起课序。</p><p>单交叉是分离的关键：高类型增加一单位教育的效用损失更小。没有它，模仿无代价，信号撑不住。</p><p>混同均衡在原文里允许存在。精炼掉混同是 Cho–Kreps 以后的工作，主干完美贝叶斯课才处理。</p><p>教育可以同时有生产效应。原文为了钉机制，先把生产关掉。经验上的教育回报不能单独「证明 Spence」。</p><p>有信息方先动，与下一篇筛选相对。次序不可对调着读成同一篇 QJE。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Spence 1973：有成本信号可分离类型，即使信号无社会产品。</li><li>信息均衡允许多重，分离可以过度教育。</li><li>发送者先行动；筛选留给下一篇。</li><li>出处：Spence, <em>QJE</em> 1973。</li></ul>',15))])}const k=t(d,[["render",h]]);export{S as __pageData,k as default};
